drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  02 · concurrency token to 409★★☆ core
//  concepts: optimistic concurrency · WHERE version = original · 409 Conflict
// ─────────────────────────────────────────────────────────────────────────
//
//  The original version goes into the WHERE clause; zero rows affected means someone got there first.

using static Bootcamp.Check;

int SaveOrder(Db db, int id, string status, int originalVersion)
{
    // UPDATE Orders SET Status = @status, Version = Version + 1 WHERE Id = @id AND Version = @originalVersion
    if (!db.Orders.TryGetValue(id, out var row) || row.Version != originalVersion)
        throw new DbUpdateConcurrencyException("The database operation was expected to affect 1 row(s), but actually affected 0 row(s).");
    db.Orders[id] = new Row(status, row.Version + 1);
    return row.Version + 1;
}

(int Status, int? Version) PutOrder(Db db, int id, string status, int ifMatchVersion)
{
    if (!db.Orders.ContainsKey(id)) return (404, null);
    try
    {
        return (200, SaveOrder(db, id, status, ifMatchVersion));
    }
    catch (DbUpdateConcurrencyException)
    {
        return db.Orders.TryGetValue(id, out var current) ? (409, current.Version) : (409, null);
    }
}

Db Seed()
{
    var db = new Db();
    db.Orders[1] = new Row("placed", 3);
    return db;
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("a matching version updates the row and bumps the version", () =>
{
    var db = Seed();
    Eq(SaveOrder(db, 1, "shipped", 3), 4);
    Eq(db.Orders[1], new Row("shipped", 4));
});

Test("a stale version throws and writes nothing", () =>
{
    var db = Seed();
    Throws<DbUpdateConcurrencyException>(() => SaveOrder(db, 1, "shipped", 2), "affected 0 row(s)");
    Eq(db.Orders[1], new Row("placed", 3));
});

Test("the second of two edits made from the same read gets 409 (no lost update)", () =>
{
    var db = Seed();
    var first = PutOrder(db, 1, "shipped", 3);
    var second = PutOrder(db, 1, "cancelled", 3);
    Eq((first, second), ((200, (int?)4), (409, (int?)4)));
    Eq(db.Orders[1].Status, "shipped");
});

Test("retrying with the version from the 409 succeeds", () =>
{
    var db = Seed();
    PutOrder(db, 1, "shipped", 3);
    var conflict = PutOrder(db, 1, "cancelled", 3);
    Eq(PutOrder(db, 1, "cancelled", conflict.Version!.Value), (200, (int?)5));
    Eq(db.Orders[1], new Row("cancelled", 5));
});

Test("a missing order is 404, not 409", () =>
    Eq(PutOrder(Seed(), 99, "shipped", 1), (404, (int?)null)));

Test("a row deleted after it was read surfaces as a concurrency conflict (boundary)", () =>
{
    var db = Seed();
    db.Orders.Remove(1);                    // another request deleted it after we loaded version 3
    Throws<DbUpdateConcurrencyException>(() => SaveOrder(db, 1, "shipped", 3));
    Eq(db.Orders.Count, 0);
});

drills.tail:
// ──────────────────────────── types ──────────────────────────────────────

/// <summary>a stored Orders row; Version is the concurrency token ([ConcurrencyCheck] / rowversion)</summary>
record Row(string Status, int Version);

class Db
{
    public Dictionary<int, Row> Orders { get; } = new();
}

class DbUpdateConcurrencyException(string message) : Exception(message);

drills.explanation:
The original version is part of the match, so a stale write matches nothing:

```csharp
if (!db.Orders.TryGetValue(id, out var row) || row.Version != originalVersion)
    throw new DbUpdateConcurrencyException("... affected 0 row(s).");
db.Orders[id] = new Row(status, row.Version + 1);
return row.Version + 1;
```

`PutOrder` answers 404 first, then maps the exception to 409 with the current version. The tests catch the plausible wrong version that matches on the id alone (last writer wins): the stale-version test sees the row overwritten and the two-edits test sees 200 twice, which is exactly the lost update the token exists to stop. A version that maps the conflict to 404 or lets the exception escape as a 500 fails the 409 tests.

