drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  03 · one transaction across two saves★★★ core
//  concepts: BeginTransaction · dispose without commit = rollback · caller-owned transactions
// ─────────────────────────────────────────────────────────────────────────
//
//  Each SaveChanges is atomic on its own. Two of them are only atomic inside one transaction.

using static Bootcamp.Check;

string PlaceOrder(Db db, string sku, int quantity, string orderId)
{
    if (quantity < 1) throw new ArgumentOutOfRangeException(nameof(quantity), "quantity must be at least 1");
    using var owned = db.CurrentTransaction is null ? db.BeginTransaction() : null;   // join the caller's transaction
    if (!db.Stock.TryGetValue(sku, out var left) || left < quantity) throw new InvalidOperationException("insufficient stock");
    db.SaveChanges(d => d.Stock[sku] -= quantity);
    db.SaveChanges(d => d.Orders.Add(orderId));
    owned?.Commit();
    return orderId;
}

Db Seed()
{
    var db = new Db();
    db.Stock["sku-1"] = 10;
    return db;
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("both saves commit together, as one commit", () =>
{
    var db = Seed();
    Eq(PlaceOrder(db, "sku-1", 3, "o1"), "o1");
    Eq((db.Stock["sku-1"], db.Orders.Count == 1 ? db.Orders[0] : null), (7, "o1"));
    Eq((db.Saves, db.Commits, db.CurrentTransaction is null), (2, 1, true));
});

Test("a failing second save rolls back the first (trap)", () =>
{
    var db = Seed();
    db.FailOnSave = 2;
    Throws<DbUpdateException>(() => PlaceOrder(db, "sku-1", 3, "o1"));
    Eq((db.Stock["sku-1"], db.Orders.Count, db.Commits), (10, 0, 0));
    Ok(db.CurrentTransaction is null, "the transaction was left open");
});

Test("the caller sees the original exception", () =>
{
    var db = Seed();
    db.FailOnSave = 1;
    Throws<DbUpdateException>(() => PlaceOrder(db, "sku-1", 3, "o1"), "save 1 failed");
    Eq(db.Stock["sku-1"], 10);
});

Test("insufficient stock writes nothing and leaves no transaction open", () =>
{
    var db = Seed();
    Throws<InvalidOperationException>(() => PlaceOrder(db, "sku-1", 11, "o1"), "insufficient stock");
    Throws<InvalidOperationException>(() => PlaceOrder(db, "sku-unknown", 1, "o2"), "insufficient stock");
    Eq((db.Saves, db.Stock["sku-1"], db.CurrentTransaction is null), (0, 10, true));
});

Test("inside the caller's transaction it neither begins nor commits", () =>
{
    var db = Seed();
    var outer = db.BeginTransaction();
    PlaceOrder(db, "sku-1", 3, "o1");
    Eq((db.Commits, db.Stock["sku-1"]), (0, 7));
    outer.Dispose();                        // the caller decides: no commit means roll back
    Eq((db.Stock["sku-1"], db.Orders.Count), (10, 0));
});

Test("a quantity below 1 is rejected before any save (boundary)", () =>
{
    var db = Seed();
    Throws<ArgumentOutOfRangeException>(() => PlaceOrder(db, "sku-1", 0, "o1"));
    Eq((db.Saves, db.CurrentTransaction is null), (0, true));
});

drills.tail:
// ──────────────────────────── types ──────────────────────────────────────

class DbUpdateException(string message) : Exception(message);

/// <summary>A tiny DbContext + database: SaveChanges autocommits unless a transaction is open.</summary>
class Db
{
    public Dictionary<string, int> Stock { get; private set; } = new();
    public List<string> Orders { get; private set; } = new();
    public Tx? CurrentTransaction { get; private set; }
    public int Saves { get; private set; }
    public int Commits { get; private set; }
    /// <summary>make the Nth SaveChanges call (1-based) fail before it writes anything</summary>
    public int FailOnSave { get; set; }

    private (Dictionary<string, int> Stock, List<string> Orders)? _before;

    public Tx BeginTransaction()
    {
        if (CurrentTransaction is not null)
            throw new InvalidOperationException("The connection is already in a transaction and cannot participate in another transaction.");
        _before = (new(Stock), new(Orders));
        return CurrentTransaction = new Tx(this);
    }

    /// <summary>one atomic SaveChanges: the change is applied completely or not at all</summary>
    public void SaveChanges(Action<Db> change)
    {
        Saves++;
        if (Saves == FailOnSave) throw new DbUpdateException($"save {Saves} failed");
        change(this);
        if (CurrentTransaction is null) Commits++;
    }

    internal void End(bool commit)
    {
        if (commit) Commits++;
        else if (_before is { } b) (Stock, Orders) = (b.Stock, b.Orders);
        _before = null;
        CurrentTransaction = null;
    }
}

class Tx(Db db) : IDisposable
{
    private bool _done;

    public void Commit()
    {
        if (_done) throw new InvalidOperationException("The transaction has completed.");
        _done = true;
        db.End(commit: true);
    }

    /// <summary>disposing without Commit rolls back, like EF Core's transaction</summary>
    public void Dispose()
    {
        if (_done) return;
        _done = true;
        db.End(commit: false);
    }
}

drills.explanation:
Open a transaction only when you own the unit of work, and let `using` roll back on any early exit:

```csharp
if (quantity < 1) throw new ArgumentOutOfRangeException(nameof(quantity));
using var owned = db.CurrentTransaction is null ? db.BeginTransaction() : null;
if (!db.Stock.TryGetValue(sku, out var left) || left < quantity) throw new InvalidOperationException("insufficient stock");
db.SaveChanges(d => d.Stock[sku] -= quantity);
db.SaveChanges(d => d.Orders.Add(orderId));
owned?.Commit();          // disposing without this line rolls back
return orderId;
```

The trap test catches the plausible wrong version that simply calls `SaveChanges` twice without a transaction: the first save autocommits, so after the second fails the stock reads 7 with no order (and the happy path shows two commits instead of one). A version that always calls `BeginTransaction` fails the caller-owned test, because the context refuses a second transaction; one that catches and wraps the exception fails the original-exception test.
